"""Build a standalone visual guide from actual application screenshots and vetted guides.

Run the UI harness first. No vendor screenshots or secret-containing MFA screens are generated.
"""
from pathlib import Path
import argparse
import base64
import html
import json
import subprocess
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--screens',default=str(ROOT/'docs/ui-test-output'));args=p.parse_args()
shots=Path(args.screens)
script="global.window={};require('./frontend/src/guides.js');process.stdout.write(JSON.stringify(window.BRAIN_GUIDES));"
guides=json.loads(subprocess.check_output(['node','-e',script],cwd=ROOT))

def image(name,caption):
    data=base64.b64encode((shots/name).read_bytes()).decode()
    return '<figure><img loading="lazy" src="data:image/png;base64,'+data+'" alt="'+html.escape(caption)+'"><figcaption>'+html.escape(caption)+'</figcaption></figure>'

sections=[]
for key,g in guides.items():
    steps=''.join('<li><h3>'+html.escape(s[0])+'</h3><p>'+html.escape(s[1])+'</p></li>' for s in g['steps'])
    links=''.join('<a href="'+html.escape(url,quote=True)+'" target="_blank" rel="noopener noreferrer">'+html.escape(label)+' &rarr;</a>' for label,url in g['links'])
    sections.append('<section id="'+key+'"><span class="tag">'+html.escape(g['tag'])+'</span><h2>'+html.escape(g['title'])+'</h2><p>'+html.escape(g['intro'])+'</p><ol class="steps">'+steps+'</ol><aside>'+html.escape(g['note'])+'</aside><div class="sources">Official sources: '+links+'</div></section>')
logo=base64.b64encode((ROOT/'frontend/assets/circlelogic-logo.svg').read_bytes()).decode()
css='''*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:#182c48;font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1120px;margin:auto;padding:48px 28px 90px}header{margin-bottom:32px}.brand{display:flex;gap:12px;align-items:center;font-weight:700}.brand img{width:40px;height:40px}h1{font-size:44px;line-height:1.1;letter-spacing:-1.8px;margin:32px 0 20px}h2{font-size:28px;letter-spacing:-.6px;margin:14px 0}h3{font-size:18px;margin:0 0 8px}p{color:#536681}section{background:white;padding:30px;border:1px solid #e3e9f2;border-radius:20px;margin:24px 0}nav{display:flex;flex-wrap:wrap;gap:12px}a{color:#2563eb;text-decoration:none}nav a{background:#eaf1ff;padding:9px 14px;border-radius:10px}aside{background:#f0f5ff;border:1px solid #dbe7ff;padding:18px;border-radius:12px;margin:20px 0;color:#36557e}figure{margin:24px 0}figure img{display:block;width:100%;border:1px solid #dce5f0;border-radius:12px}figcaption{font-size:13px;color:#60738d;margin-top:8px}.tag{font-size:12px;letter-spacing:.5px;text-transform:uppercase;color:#2859a4;background:#edf3ff;padding:6px 9px;border-radius:6px}.steps{padding-left:26px}.steps li{padding-left:8px;margin:24px 0}.steps li::marker{color:#2563eb;font-weight:700}.sources{font-size:14px;display:flex;flex-wrap:wrap;gap:12px;border-top:1px solid #e5ebf4;padding-top:18px}code{background:#eef2f8;padding:2px 6px;border-radius:4px}pre{background:#132740;color:#eff5ff;padding:20px;overflow:auto;border-radius:12px}pre code{background:none;padding:0}.small{font-size:14px}footer{color:#718299;font-size:13px;margin-top:30px}@media(max-width:650px){main{padding:24px 14px}section{padding:20px}h1{font-size:34px}}@media print{body{background:white}section{break-inside:avoid}a{color:inherit}nav{display:none}main{padding:0}figure{break-inside:avoid}}'''
body='<header><div class="brand"><img src="data:image/svg+xml;base64,'+logo+'" alt="Circle Logic logo">CircleLogic OS / Brain Products</div><h1>Connect your systems.<br>Know what happens next.</h1><p>A practical setup guide for the Real Estate Brain, version 04. Reviewed 25 September 2026.</p><aside><strong>These are actual CircleLogic OS screenshots.</strong> They show a synthetic testing workspace with no live provider connections. Vendor instructions below link to official documentation; private vendor screens have not been photographed or invented. Three adapters still require approved access and implementation.</aside><nav><a href="#app">Using the application</a>'+''.join('<a href="#'+key+'">'+html.escape({'microsoft':'Calendar'}.get(key,g['title'].replace('Connect ','')))+'</a>' for key,g in guides.items())+'</nav></header>'
body+='<section id="app"><span class="tag">Actual application screens</span><h2>From sign-in to a connected dashboard</h2><h3>1. Sign in to the right workspace</h3><p>Start the full application, then sign in. The local testing username is <code>testing123</code> and its password is <code>testing12345</code>. The first sign-in requires your own authenticator enrolment and recovery-code storage. Use unique private credentials for real customers. Never publish authenticator QR codes or recovery codes.</p>'+image('application-login.png','Actual first screen: username and password before any workspace data is accessible.')
body+='<h3>2. Open API Connections</h3><p>The five systems appear in one panel. Select <strong>Add API</strong> beside an implemented source. Use <strong>Unsure how to get API keys?</strong> for official access routes. A source that is pending adapter development shows an access checklist instead of accepting secrets.</p>'+image('application-connections.png','Actual API Connections page in a fresh testing workspace. All sources start disconnected.')
body+='<h3>3. Enter or upload approved credentials</h3><p>For REA, fill the partner Client ID, Client secret and authorised Agency ID. A JSON upload fills the form but does not save it. Confirm the file uses exactly the fields shown. Use approved HTTPS infrastructure for real client secrets, not this development screenshot environment.</p>'+image('secure-connection-blank.png','Actual blank REA credential dialog. No secrets are pictured.')
body+='<h3>4. Save, then authorise or sync</h3><p><strong>Credentials saved</strong> is not the same as connected. Microsoft requires an additional consent redirect. Select <strong>Sync now</strong> to import the supported data. Failed requests do not create example values.</p>'+image('credentials-saved.png','Actual saved-credential state using synthetic test values. The secret is not returned or displayed.')
body+='<h3>5. Read only verified imported data</h3><p>Until a source has a successful import, the relevant widgets stay empty. A successful empty import is shown as zero records, while unavailable data is not misrepresented as zero. REA report events are not buyer-intent scores.</p>'+image('application-dashboard-empty.png','Actual full-application dashboard before sources are connected. No placeholder customers, figures or appointments.')+'</section>'
body+=''.join(sections)
body+='<section><h2>JSON formats for implemented connections</h2><p>Replace these empty strings with approved values only inside your protected working environment. Never paste credential files into a chat.</p><h3>REA listing reports</h3><pre><code>'+html.escape(json.dumps({'client_id':'','client_secret':'','agency_id':''},indent=2))+'</code></pre><h3>Microsoft calendar</h3><pre><code>'+html.escape(json.dumps({'directory_id':'','client_id':'','client_secret':''},indent=2))+'</code></pre><p><code>directory_id</code> is Microsoft\'s Directory (tenant) ID. The secret is its value, not its Secret ID. Agentbox, RP Data and Proping deliberately have no guessed credential templates.</p></section><footer>CircleLogic OS v04. Screenshots of the implemented application; no customer data or provider-account validation. This guide is not a statement that gated integrations can be enabled by uploading a key.</footer>'
page='<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'; base-uri \'none\'; form-action \'none\'"><title>CircleLogic OS v04 - illustrated setup guide</title><style>'+css+'</style></head><body><main>'+body+'</main></body></html>'
(ROOT/'docs/SETUP-GUIDE.html').write_text(page)
text='# Five requested connections - v04\n\nVerified public routes reviewed 25 September 2026. This is the shipped implementation status, not a promise of approved vendor access.\n\n'
for key,g in guides.items():
    text+='## '+g['title']+'\n\n**'+g['tag']+'**\n\n'+g['intro']+'\n\n'
    for i,(a,b) in enumerate(g['steps'],1):text+=f'{i}. **{a}.** {b}\n'
    text+='\n'+g['note']+'\n\n'+' | '.join('['+a+']('+b+')' for a,b in g['links'])+'\n\n'
text+='## Report semantics\n\nREA metrics select only realestate_au / all / listingEvents / period=all. pageView maps to page_views, emailEnquiry to email_enquiries, and listingSaved to saves. Missing values remain null; daily and total values are never added together. These are report-period event counts, not unique people or intent scores. Official contract: https://partner.realestate.com.au/campaign/listing-performance/usage/\n\nCalendar imports cover the next 30 days. The UI uses Australia/Sydney display time and a 7/30-day filter. No mailbox reads or calendar writes are performed.\n\n## Next build gate\n\nFor each pending adapter, obtain the exact approved authentication and endpoint contract, agency/user entitlement, sample success/empty/error payloads, pagination, rate limits, data mapping and retention rules. Add atomic sync and cross-tenant tests before changing implemented=false or accepting credentials. This release has no endpoint for uploading an invented normalized file as though it came from a provider.\n'
(ROOT/'docs/INTEGRATIONS.md').write_text(text)
print('Built',ROOT/'docs/SETUP-GUIDE.html',len(page.encode()),'bytes')
